mapper.select:

SELECT MAX(trade_date)
FROM trading_calendar
WHERE trade_date BETWEEN #{start} AND #{end}
  AND exchange='SSE'
  AND is_open=1
  AND is_synthetic=#{synthetic}


SELECT source
FROM daily_bar
WHERE instrument_id=#{id}
  AND is_synthetic=#{synthetic}
  AND trade_date<=#{date}
ORDER BY trade_date DESC, fetched_at DESC, id DESC
LIMIT 1


SELECT DISTINCT trade_date
FROM trading_calendar
WHERE trade_date BETWEEN #{start} AND #{end}
  AND is_open=1
  AND is_synthetic=#{synthetic}
ORDER BY trade_date


SELECT COUNT(DISTINCT trade_date)
FROM trading_calendar
WHERE trade_date BETWEEN #{start} AND #{end}
  AND is_synthetic=#{synthetic}


SELECT trade_date
FROM instrument_day_status
WHERE instrument_id=#{instrumentId}
  AND source=#{source}
  AND is_synthetic=#{synthetic}
  AND status='SUSPENDED'
  AND trade_date BETWEEN #{startDate} AND #{endDate}

mapper.delete:

DELETE FROM daily_bar
WHERE instrument_id=#{instrumentId}
  AND trade_date=#{tradeDate}
  AND source=#{source}
  AND is_synthetic=#{synthetic}


DELETE FROM adjustment_factor
WHERE instrument_id=#{instrumentId}
  AND trade_date=#{tradeDate}
  AND source=#{source}
  AND is_synthetic=#{synthetic}


DELETE FROM instrument_day_status
WHERE instrument_id=#{instrumentId}
  AND trade_date=#{tradeDate}
  AND source=#{source}
  AND is_synthetic=#{synthetic}

mapper.select:
SELECT r.source FROM market_data_revision r JOIN instrument i ON i.id=r.instrument_id
WHERE i.symbol=#{symbol} AND r.is_synthetic=#{synthetic}
  AND r.trade_date BETWEEN #{startDate} AND #{endDate}
  AND r.algorithm_version='RAW_V2' AND r.recorded_at < DATE_ADD(r.trade_date, INTERVAL 1 DAY)
  AND r.fetched_at < DATE_ADD(r.trade_date, INTERVAL 1 DAY)
GROUP BY r.source ORDER BY MAX(r.trade_date) DESC, MAX(r.id) DESC
